": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "d285df55-870d-bcef-c6cf-e6cc22070826", "sort_order": 0, "title": "Hawa Mahal (Palace of Winds)", "description": "Whispers of history in wind.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "9d99bedd-2811-58a8-0bb7-ffe0e68fd6fd", "sort_order": 1, "title": "City Palace", "description": "Royal legacy, echoes of sovereignty.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "ca740123-ec8c-723e-a633-e42e7a5a76c4", "sort_order": 2, "title": "Observatory / Jantar Mantar", "description": "Celestial marvels, antique astronomy.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "88204920-0717-52ed-a8ca-cb0727438df5", "sort_order": 3, "title": "Jal Mahal (Water Palace)", "description": "Peaceful waters, regal reflection.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "624f7fa1-24dd-fcee-159b-44191a053d6e", "sort_order": 4, "title": "Amer Fort", "description": "Strength in stone, stories unfold.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "88464a9d-5eda-4968-2270-688cb39e239a", "sort_order": 5, "title": "Nahargarh Fort", "description": "Sentinel of Jaipur, royal views.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "p